package com.alpharip.staffmod.IncidentPostMortemBoard; public final class IncidentRootCause { private String summary,contributingFactors,analysisOwner; private long reviewedAt; public IncidentRootCause(){} public IncidentRootCause(String s,String f,String o,long t){if(s==null||s.trim().isEmpty())throw new IllegalArgumentException("Root cause required");summary=s.trim();contributingFactors=clean(f);analysisOwner=clean(o);if(t<=0)throw new IllegalArgumentException("Timestamp must be positive");reviewedAt=t;} public String getSummary(){return summary;} public String getContributingFactors(){return contributingFactors;} public String getAnalysisOwner(){return analysisOwner;} public long getReviewedAt(){return reviewedAt;} private static String clean(String s){return s==null?"":s.trim();} }